-- Read-only schema/policy snapshot; no user records, DDL or mutations.
SELECT jsonb_build_object(
  'tables', (SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'rls_enabled',c.relrowsecurity,'rls_forced',c.relforcerowsecurity,'owner',pg_catalog.pg_get_userbyid(c.relowner),'ACL',c.relacl::text,'options',c.reloptions)), '[]'::jsonb) FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('chat_sessions','session_files','chat_messages','workflow_steps','shared_files','messages')),
  'policies', (SELECT coalesce(jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'name',policyname,'permissive',permissive,'roles',roles,'command',cmd,'using',qual,'with_check',with_check)), '[]'::jsonb) FROM pg_catalog.pg_policies WHERE schemaname='public' AND tablename IN ('chat_sessions','session_files','chat_messages','workflow_steps','shared_files','messages')),
  'columns', (SELECT coalesce(jsonb_agg(jsonb_build_object('table',table_name,'name',column_name,'data_type',data_type,'nullable',is_nullable)), '[]'::jsonb) FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('chat_sessions','session_files','chat_messages','workflow_steps','shared_files','messages')),
  'views', (SELECT coalesce(jsonb_agg(jsonb_build_object('name',c.relname,'definition',pg_catalog.pg_get_viewdef(c.oid,true),'options',c.reloptions)), '[]'::jsonb) FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='v' AND c.relname IN ('messages','chat_messages','workflow_steps','session_files'))
) AS snapshot;
